attributes.twig:
{
{#- Last Updated by Dylan 2026-10-26 -#}
{% set type_mapping = {
  "Shows" : "Series",
  "Subseries" : "Subseries",
  "Season" : "Season",
  "Episodes": "Episode",
  } %}
  "label": {{ data.label|json_encode|raw }},
  {%- if data.nypr_episode_title is defined and data.nypr_episode_title is not empty %}
  "label_alt" : {{ data.nypr_episode_title|json_encode|raw }},
  {% endif -%}
  "type": {{ type_mapping[data.type]|default("Collection")|json_encode|raw }},
  {% set local_identifiers = [] %}
  {% for local_id in data.nypr_external_identifier_type_and_identifier|default([]) %}
     {% set local_id_split = local_id|split('(') %}
     {% set local_identifiers = local_identifiers|merge([{"source": local_id_split[0]|default('Undefined'), "value": local_id_split[1]|default('none')|trim(')')}]) %}
  {% endfor %}
  "local_identifiers": {{ local_identifiers|json_encode|raw }},
  {%- if data.dates_etdf is defined and data.dates_etdf is not empty %}
  "dates_edtf" : {{ data.dates_etdf|json_encode|raw }},
  {% endif -%}
  "source_system": {{ data.source_system|default("Publisher")|json_encode|raw }},
  "minimum_viable_metadata_present": "Yes",
  "as:generator": {
        "type": "Create",
        "actor": {
            "url": {{ setURL|json_encode|raw }},
            "name": "ami",
            "type": "Service"
        },
        "endTime": "{{"now"|date("c")}}",
        "summary": "Generator",
        "@context": "https:\/\/www.w3.org\/ns\/activitystreams"
     }
}
